/* Toolbox Print Studio: mobile-first print preview; no uploaded data leaves the device. */
(()=>{'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let urls=[],busy=false,items=[];
const cleanup=()=>{urls.forEach(u=>URL.revokeObjectURL(u));urls=[];items=[]};
function close(){document.getElementById('tbPrintDialog')?.close();cleanup()}
function ensure(){let d=document.getElementById('tbPrintDialog');if(d)return d;d=document.createElement('dialog');d.id='tbPrintDialog';d.className='tb-print-dialog';d.innerHTML='<div class="tb-print-shell"><div class="tb-print-head"><div><span class="tb-print-eyebrow">TOOLBOX DOCUMENTS</span><h2>Print Studio</h2></div><button type="button" class="tb-print-close" aria-label="Close print preview">×</button></div><div class="tb-print-content"><p class="tb-print-note">Preview and prepare your document for printing. The original file will not be changed.</p><div class="tb-print-preview" id="tbPrintPreview"></div><div class="tb-print-controls"><label>Paper size<select id="tbPrintPaper"><option value="A4">A4</option><option value="letter">US Letter</option><option value="legal">Legal</option></select></label><label>Orientation<select id="tbPrintOrientation"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></label><label>Pages<select id="tbPrintPages"><option value="all">All available</option><option value="front">Front / first page</option><option value="back">Back / second page</option></select></label><label>Image size<select id="tbPrintScale"><option value="contain">Fit to paper</option><option value="actual">Original image size (up to page bounds)</option></select></label><label>Copies<input id="tbPrintCopies" type="number" min="1" max="20" value="1" inputmode="numeric"></label></div><p class="tb-print-note">Printer selection and final copy settings are provided by your phone or printer. Save as PDF may be available in the native print menu.</p></div><div class="tb-print-footer"><button type="button" class="tb-print-secondary" id="tbPrintCancel">Cancel</button><button type="button" class="tb-print-primary" id="tbPrintGo">Print / Save PDF</button></div></div>';document.body.append(d);d.querySelector('.tb-print-close').onclick=close;d.querySelector('#tbPrintCancel').onclick=close;d.addEventListener('close',cleanup);d.addEventListener('click',e=>{if(e.target===d)close()});d.querySelectorAll('select').forEach(x=>x.addEventListener('change',preview));d.querySelector('#tbPrintGo').onclick=print;return d}
function preview(){const d=ensure(),paper=d.querySelector('#tbPrintPaper').value,orientation=d.querySelector('#tbPrintOrientation').value,pages=d.querySelector('#tbPrintPages').value,scale=d.querySelector('#tbPrintScale').value;let chosen=items.filter(x=>pages==='all'||(pages==='front'&&x.side!=='back')||(pages==='back'&&x.side==='back'));d.querySelector('#tbPrintPreview').innerHTML=chosen.length?chosen.map((x,i)=>`<div class="tb-print-paper ${orientation==='landscape'?'tb-print-landscape':''}"><div class="tb-print-paper-inner">${x.pdf?`<div class="tb-print-pdf">PDF attachment<br><small>Use the native PDF viewer to print this file.</small></div>`:`<img src="${x.url}" alt="${esc(x.side)} document page" class="${scale==='actual'?'tb-print-actual':''}">`}</div><span>Page ${i+1} of ${chosen.length} · ${esc(paper)} · ${esc(x.side)}</span></div>`).join(''):'<p class="tb-print-empty">No image available for this page selection.</p>'}
async function open(id){if(busy)return;busy=true;try{cleanup();for(const side of ['front','back','page']){let blob=await photoOperation(id+'::'+side,'read');if(!blob&&side==='page')blob=await photoOperation(id,'read');if(blob){const url=URL.createObjectURL(blob);urls.push(url);items.push({side,url,pdf:blob.type==='application/pdf',blob})}}if(!items.length){alert('No saved attachment to print. Save an image or PDF first.');return}const d=ensure();d.showModal();d.querySelector('#tbPrintPages').value='all';d.querySelector('#tbPrintCopies').value='1';preview()}catch(e){alert('Unable to prepare the print preview. Please try again.')}finally{busy=false}}
function print(){const d=ensure(),pages=d.querySelector('#tbPrintPages').value,selected=items.filter(x=>pages==='all'||(pages==='front'&&x.side!=='back')||(pages==='back'&&x.side==='back'));if(!selected.length)return alert('No pages selected.');if(selected.some(x=>x.pdf)){if(selected.length!==1)return alert('Print PDF files separately from images.');const a=document.createElement('a');a.href=selected[0].url;a.target='_blank';a.rel='noopener';a.click();return}const orientation=d.querySelector('#tbPrintOrientation').value,paper=d.querySelector('#tbPrintPaper').value,scale=d.querySelector('#tbPrintScale').value,copies=Math.min(20,Math.max(1,Number(d.querySelector('#tbPrintCopies').value)||1));const css=`@page{size:${paper==='letter'?'letter':paper==='legal'?'legal':'A4'} ${orientation};margin:10mm}*{box-sizing:border-box}body{margin:0;background:white}.sheet{height:calc(100vh - 20mm);page-break-after:always;display:flex;align-items:center;justify-content:center}.sheet:last-child{page-break-after:auto}img{display:block;max-width:100%;max-height:100%;object-fit:contain;${scale==='actual'?'width:auto;height:auto;':'width:100%;height:100%;'}}`;
// A user-initiated window.open is used to avoid asynchronous popup blocking on mobile.
const win=window.open('','_blank');if(!win){alert('Your browser blocked the print window. Allow pop-ups for this site, then try again.');return}const pagesHtml=Array.from({length:copies},()=>selected.map(x=>`<div class="sheet"><img src="${x.url}" alt="Document image"></div>`).join('')).join('');win.document.open();win.document.write(`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Toolbox Print Studio</title><style>${css}</style></head><body>${pagesHtml}<script>window.addEventListener('load',()=>{Promise.all(Array.from(document.images).map(i=>i.decode().catch(()=>{}))).then(()=>setTimeout(()=>window.print(),350))});<\/script></body></html>`);win.document.close()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-print-doc-side]');if(!b)return;e.preventDefault();const id=b.dataset.printRecord;if(id)open(id)});
})();
